import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import {
    CButton,
    CCol,
    CContainer,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow,
} from '@coreui/react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import MaterialReactTable from 'material-react-table';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "InstagramProfiles.js";

const initialState = {
    isLoaded: false,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    profileListData: [],
    page: 1,
    size: 50,
    totalPages: 0,
    totalElements: 0,
    search: '',
};

const tableColumnData = [
    {
        accessorKey: 'id',
        header: 'ID',
        size: 60,
    },
    {
        accessorKey: 'profilePicUrl',
        header: 'Pic',
        size: 80,
        enableSorting: false,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <img src={renderedCellValue} alt="profile" style={{ width: '50px', height: '50px', borderRadius: '50%' }} />
                : '—'
        ),
    },
    {
        accessorKey: 'username',
        header: 'Username',
    },
    {
        accessorKey: 'fullName',
        header: 'Full Name',
    },
    {
        accessorKey: 'bio',
        header: 'Bio',
        size: 250,
        Cell: ({ renderedCellValue }) => (
            <span title={renderedCellValue} style={{ display: 'block', maxWidth: '250px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {renderedCellValue || '—'}
            </span>
        ),
    },
    {
        accessorKey: 'followersCount',
        header: 'Followers',
        size: 100,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue != null ? renderedCellValue.toLocaleString() : '—'
        ),
    },
    {
        accessorKey: 'link',
        header: 'Link',
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <a href={renderedCellValue} target="_blank" rel="noopener noreferrer">Profile</a>
                : '—'
        ),
    },
    {
        accessorKey: 'isVerified',
        header: 'Verified',
        size: 80,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue ? '✅' : '❌'
        ),
    },
    {
        accessorKey: 'createdOn',
        header: 'Added On',
        size: 180,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue ? moment(renderedCellValue).format('YYYY/MM/DD HH:mm:ss ddd') : '—'
        ),
    },
];

class InstagramProfiles extends Component {

    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    reloadData() {
        this.resetStateToDefault();
        setTimeout(() => this.fetchProfileList(), 0);
    }

    componentDidMount() {
        document.title = "Instagram Profiles";
        this.fetchProfileList();
    }

    navigateToProfile = (internalProfileId) => {
        this.props.history.push('/instagram/profile/' + internalProfileId);
    }

    fetchProfileList() {
        const { page, size, search } = this.state;
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/profiles';
        const userData = getUserDataFromLocalStorage();

        const reqData = { page, size, search: search || null };
        Logger(FILE_NAME, "fetchProfileList", "", "reqData", reqData);

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({ failureModalVisible: true });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchProfileList", "FETCH_1", "result", result);
                const pageData = result.data;
                this.setState({
                    isLoaded: true,
                    profileListData: pageData.content || [],
                    totalPages: pageData.totalPages || 0,
                    totalElements: pageData.totalElements || 0,
                });
            },
            (error) => {
                Logger(FILE_NAME, "fetchProfileList", "FETCH_1", "error", error);
                this.setState({ failureModalVisible: true });
            }
        );
    }

    handleSearchChange = (event) => {
        this.setState({ search: event.target.value });
    }

    handleSearchSubmit = (event) => {
        event.preventDefault();
        this.setState({ page: 1 }, () => this.fetchProfileList());
    }

    handlePrevPage = () => {
        if (this.state.page > 1) {
            this.setState({ page: this.state.page - 1 }, () => this.fetchProfileList());
        }
    }

    handleNextPage = () => {
        if (this.state.page < this.state.totalPages) {
            this.setState({ page: this.state.page + 1 }, () => this.fetchProfileList());
        }
    }

    render() {
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ?
            <div>
                <h1>Instagram Profiles &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                    <CButton color="secondary" className="px-4" onClick={() => this.props.history.push('/instagram')}>← Back</CButton>
                    &nbsp;
                    <CButton color="success" className="px-4" onClick={() => this.reloadData()}>Reload Data</CButton>
                </h1>
                <br />

                {/* Search bar */}
                <CContainer className="mb-3">
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <form onSubmit={this.handleSearchSubmit}>
                                <CInputGroup>
                                    <CInputGroupPrepend>
                                        <CInputGroupText>🔍</CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="Search profiles (username, name, bio, link)..."
                                        type="text"
                                        value={this.state.search}
                                        onChange={this.handleSearchChange}
                                    />
                                    <CButton color="primary" type="submit" className="ml-2">Search</CButton>
                                </CInputGroup>
                            </form>
                        </CCol>
                    </CRow>
                </CContainer>

                {/* Profiles table */}
                <MaterialReactTable
                    initialState={{ density: 'compact' }}
                    columns={[
                        ...tableColumnData.slice(0, 6), // ID, Pic, Username, Full Name, Bio, Followers
                        {
                            accessorKey: 'actions',
                            header: 'Actions',
                            size: 100,
                            enableSorting: false,
                            Cell: ({ row }) => (
                                <CButton
                                    color="info"
                                    size="sm"
                                    onClick={() => this.navigateToProfile(row.original.id)}
                                >
                                    View
                                </CButton>
                            ),
                        },
                        ...tableColumnData.slice(6), // Link, Verified, Added On
                    ]}
                    data={this.state.profileListData}
                    enablePagination={false}
                    enableEditing={false}
                />

                {/* Pagination controls */}
                <CContainer className="mt-3">
                    <CRow className="justify-content-center align-items-center">
                        <CCol md="6" className="text-center">
                            <CButton
                                color="secondary"
                                disabled={this.state.page <= 1}
                                onClick={this.handlePrevPage}
                            >
                                ← Prev
                            </CButton>
                            &nbsp;&nbsp;
                            <span>
                                Page <strong>{this.state.page}</strong> of <strong>{this.state.totalPages}</strong>
                                &nbsp;({this.state.totalElements} total profiles)
                            </span>
                            &nbsp;&nbsp;
                            <CButton
                                color="secondary"
                                disabled={this.state.page >= this.state.totalPages}
                                onClick={this.handleNextPage}
                            >
                                Next →
                            </CButton>
                        </CCol>
                    </CRow>
                </CContainer>

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
            : <Loading />
        );
    }
}

export default InstagramProfiles;
